<script setup lang="ts">import { computed, ref, onMounted } from 'vue'; import { Plus, Search, SlidersHorizontal } from 'lucide-vue-next'; import PageHeader from '../components/PageHeader.vue'; import TaskRow from '../components/TaskRow.vue'; import EmptyState from '../components/EmptyState.vue'; import { useTasksStore } from '../stores/tasks'; import { useAppStore } from '../stores/app'; import { api } from '../api/client'; const store = useTasksStore(); const app = useAppStore(); const filter = ref('pending'); const query = ref(''); const showForm = ref(false); const title = ref(''); const filtered = computed(() => store.items.filter(t => (filter.value === 'all' || t.status === filter.value) && (!query.value || `${t.title} ${t.course || ''}`.toLowerCase().includes(query.value.toLowerCase())))); onMounted(() => store.load()); async function submit() { if (!title.value.trim()) return; try { const task = await api.createTask({ title: title.value.trim(), category: 'other', priority: 'normal' }); store.items.unshift(task); title.value = ''; showForm.value = false; app.toast('任务已添加') } catch (e) { app.toast(e instanceof Error ? e.message : '添加失败') } } async function action(id:number, action:'complete'|'dismiss') { try { await store.mutate(id, action); app.toast(action === 'complete' ? '任务已完成' : '任务已忽略') } catch { app.toast('保存失败，已恢复原状态') } }</script>
<template><section class="page-content"><PageHeader eyebrow="任务中心" title="任务" description="所有从消息中提取或手动添加的校园事务。"><button class="button button-primary" @click="showForm = !showForm"><Plus :size="16" />新建任务</button></PageHeader><form v-if="showForm" class="inline-form panel" @submit.prevent="submit"><label for="new-task">任务名称</label><div class="inline-form-row"><input id="new-task" v-model="title" placeholder="例如：提交高数作业" autofocus /><button class="button button-primary" type="submit">添加</button></div></form><div class="toolbar"><div class="segmented"><button v-for="item in [{id:'pending',label:'进行中'},{id:'completed',label:'已完成'},{id:'all',label:'全部'}]" :key="item.id" :class="{ active: filter === item.id }" @click="filter = item.id">{{ item.label }}</button></div><label class="search-box"><Search :size="16" /><input v-model="query" aria-label="搜索任务" placeholder="搜索任务或课程" /></label><button class="icon-button filter-button" aria-label="筛选"><SlidersHorizontal :size="18" /></button></div><div class="task-page-layout"><section class="panel"><div class="list-heading"><strong>{{ filtered.length }} 个任务</strong><span v-if="store.loading" class="loading-label">正在同步…</span></div><div v-if="filtered.length" class="task-list"><TaskRow v-for="task in filtered" :key="task.id" :task="task" @complete="action(task.id, 'complete')" @dismiss="action(task.id, 'dismiss')" /></div><EmptyState v-else title="没有匹配的任务" description="调整筛选条件，或创建一个新的校园事务。"><button class="text-link button-reset" @click="showForm = true">新建任务</button></EmptyState></section><aside class="panel task-aside"><p class="section-kicker">任务原则</p><h3>先做下一步，不必一次整理所有事。</h3><p class="muted-copy">截止时间会按你的本地时区显示。任务状态的改变会先即时反馈，保存失败时会自动恢复。</p></aside></div></section></template>
